# Let me create a strategy to fill closed rectangular regions
# First, let me implement detection and filling

def find_filled_rectangles(grid):
    """Find rectangular regions that are completely filled with 1s"""
    height = len(grid)
    width = len(grid[0])

    # Find all rectangles that have all 1s
    rectangles = []

    for r in range(height):
        for c in range(width):
            if grid[r][c] == 1:
                # Try to find a rectangle with this as top-left
                for h in range(1, height - r + 1):
                    for w in range(1, width - c + 1):
                        # Check if this region is all 1s
                        all_ones = True
                        for dr in range(h):
                            for dc in range(w):
                                if grid[r + dr][c + dc] == 0:
                                    all_ones = False
                                    break
                            if not all_ones:
                                break
                        if all_ones:
                            rectangles.append((r, c, h, w))

    return rectangles

# Find completely filled 1 rectangles
filled = find_filled_rectangles(grid)
print(f"Found {len(filled)} completely filled rectangles")
for rect in filled[:10]:
    print(f"  {rect} : rows {rect[0]}-{rect[0]+rect[2]-1}, cols {rect[1]}-{rect[1]+rect[3]-1}")

# Let me detect rectangular frames (hollow rectangles with 1s as border and 0s inside)
def find_rectangular_frames(grid):
    """Find rectangular frames that enclose 0s"""
    height = len(grid)
    width = len(grid[0])
    frames = []

    for r in range(height - 1):
        for c in range(width - 1):
            if grid[r][c] == 1:  # potential top-left corner
                # Find extent of this frame
                # Go right to find top edge extent
                top_row = r
                for dc in range(width - 1 - c):
                    if grid[r][c + dc] == 1:
                        pass  # continue
                    elif grid[r][c + dc] == 0:
                        break  # not a continuous edge

                # Check if this could be a frame rect
                for h in range(2, height - r):  # at least 2 rows for a frame
                    for w in range(2, width - c):  # at least 2 cols for a frame
                        # Check if this forms a valid rectangular frame
                        top_border_ok = all(grid[r][c + dc] == 1 for dc in range(w))
                        bottom_border_ok = all(grid[r + h - 1][c + dc] == 1 for dc in range(w))
                        left_border_ok = all(grid[r + dr][c] == 1 for dr in range(h))
                        right_border_ok = all(grid[r + dr][c + w - 1] == 1 for dr in range(h))

                        if top_border_ok and bottom_border_ok and left_border_ok and right_border_ok:
                            # Check if interior is all 0s (or doesn't contain any 1s)
                            interior_clear = all(
                                grid[r + dr][c + dc] == 0 
                                for dr in range(1, h - 1)
                                for dc in range(1, w - 1)
                            )

                            if interior_clear:
                                frames.append((r, c, h, w))

    return frames

frames = find_rectangular_frames(grid)
print(f"Found {len(frames)} rectangular frames")
for frame in frames[:10]:
    print(f"  {frame}")

