# Let me filter to only maximal rectangles (largest for each top-left corner)
def find_maximal_rectangles(grid):
    height = len(grid)
    width = len(grid[0])
    maximal = []

    # First find all rectangles
    all_rects = []
    for r in range(height):
        for c in range(width):
            if grid[r][c] == 1:
                top_right = c
                while top_right + 1 < width and grid[r][top_right + 1] == 1:
                    top_right += 1

                for h in range(1, height - r + 1):
                    bottom = r + h - 1
                    if not all(grid[bottom][col] == 1 for col in range(c, top_right + 1)):
                        continue
                    left_ok = all(grid[row][c] == 1 for row in range(r, bottom + 1))
                    right_ok = all(grid[row][top_right] == 1 for row in range(r, bottom + 1))
                    if left_ok and right_ok:
                        all_rects.append((r, c, h, top_right - c + 1))

    # Now keep only maximal - largest (h, w) for each (r, c)
    best_for = {}
    for rect in all_rects:
        r, c, h, w = rect
        key = (r, c)
        if key not in best_for or h + w > best_for[key][0] + best_for[key][1]:
            best_for[key] = (h, w)

    return [(r, c, h, w) for (r, c), (h, w) in best_for.items()]

maximal_rects = find_maximal_rectangles(grid)
print(f"Found {len(maximal_rects)} maximal rectangular frames")
for rect in maximal_rects:
