    print(f"Rows {r}-{r+h-1}, cols {c}-{c+w-1}")

# Find all complete hollow rectangular frames
def find_hollow_frames(grid):
    height = len(grid)
    width = len(grid[0])
    frames = []

    for r in range(height - 1):
        for c in range(width - 1):
            # Try to find frames starting at this position
            for h in range(2, height - r + 1):
                for w in range(2, width - c + 1):
                    r2, c2 = r + h - 1, c + w - 1

                    # Check if border is all 1s
                    top = all(grid[r][col] == 1 for col in range(c, c + w))
                    bottom = all(grid[r2][col] == 1 for col in range(c, c + w))
                    left = all(grid[row][c] == 1 for row in range(r, r + h))
                    right = all(grid[row][c2] == 1 for row in range(r, r + h))

                    if top and bottom and left and right:
                        # Check interior is all 0s
                        interior = all(
                            grid[row][col] == 0
                            for row in range(r + 1, r + h - 1)
                            for col in range(c + 1, c + w - 1)
                        )

                        if interior:
                            frames.append((r, c, h, w))

    return frames

return_hr = find_hollow_frames(grid)
print(f"Found {len(return_hr)} complete hollow rectangular frames")

# Show unique frames (sort by size)
return_hr_unique = sorted(set(return_hr))
print("\nUnique hollow frames:")
