# Let me scan the entire grid for rectangular frames systematically
# For each top-left corner with 1, find all complete rectangular borders

height = len(grid)
width = len(grid[0])
found_frames = set()

for r_start in range(height):
    for c_start in range(width):
        if grid[r_start][c_start] != 1:
            continue

        # Find where this horizontal line ends
        c_end = c_start
        while c_end + 1 < width and grid[r_start][c_end + 1] == 1:
            c_end += 1

        # Try different heights
        for h_end in range(r_start + 1, height):
            for c_test in range(c_start, min(c_end + 1, width)):
                # Check if this forms a rectangular frame
                # Top: all 1s from (r_start, c_test) to (r_start, c_end)
                if not all(grid[r_start][col] == 1 for col in range(c_test, c_end + 1)):
                    continue

                # Check if bottom row has 1s at arbitrary corner to c_end
                r_end = h_end
                if not all(grid[r_end][col] == 1 for col in range(c_test, c_end + 1)):
                    continue

                # Check left and right edges
                if not all(grid[row][c_test] == 1 for row in range(r_start, r_end + 1)):
                    continue
                if not all(grid[row][c_end] == 1 for row in range(r_start, r_end + 1)):
                    continue

                # Check interior is empty
                interior_ok = True
                for row in range(r_start + 1, r_end):
                    for col in range(c_test + 1, c_end):
                        if grid[row][col] == 1:
                            interior_ok = False
                            break
                    if not interior_ok:
                        break

                if interior_ok:
                    frame = (r_start, c_test, r_end, c_end)
                    if frame not in found_frames:
                        found_frames.add(frame)
                        print(f"Frame: R{r_start}-{r_end}, C{c_test}-{c_end} (size {(r_end-r_start+1)}x{(c_end-c_test+1)})")

print(f"\nTotal unique hollow frames: {len(found_frames)}")

